'use strict';
let creatorMode='create',pendingSlot=-1,previewJob='swordsman';
const BRANCHES=[{id:'greatsword',icon:'⚔',summary:'ฟันกว้างและหนัก · โจมตีช้าลง',tag:'โจมตีหมู่'},{id:'guardian',icon:'▣',summary:'ดาบมือเดียวกับโล่ · ป้องกันสูงขึ้น',tag:'ทนทาน'},{id:'spearman',icon:'➶',summary:'แทงได้ไกล · คุมระยะเข้าปะทะ',tag:'ระยะโจมตี'}];
function renderRatings(job){const data=JOBS[job];$('ratings').replaceChildren();[['AOE','โจมตีหมู่'],['Easy','เล่นง่าย'],['Endurance','ความทนทาน']].forEach(([name,thai],i)=>{const row=document.createElement('div');row.className='rating-row';const label=document.createElement('div');label.className='rating-name';label.textContent=name;const small=document.createElement('small');small.textContent=thai;label.append(small);const cells=document.createElement('div');cells.className='rating-cells';cells.setAttribute('role','meter');cells.setAttribute('aria-label',name+' / '+thai);cells.setAttribute('aria-valuemin','0');cells.setAttribute('aria-valuemax','5');cells.setAttribute('aria-valuenow',String(data.ratings[i]));for(let n=0;n<5;n++){const cell=document.createElement('span');if(n<data.ratings[i])cell.className='filled';cells.append(cell)}row.append(label,cells);$('ratings').append(row)})}
function drawCharacterPreview(){const old=ctx;try{ctx=$('characterPreview').getContext('2d');ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,280,240);ctx.save();ctx.translate(140,185);ctx.scale(2.3,2.3);drawPlayer({name:$('characterName').value.trim()||'Fern',job:previewJob,x:0,y:0,ground:true,vx:0,face:1,invuln:0,haste:0,swing:0});ctx.restore()}finally{ctx=old}}
function updateCareerPreview(){const creating=creatorMode==='create';$('previewTier').textContent=previewJob==='swordsman'?'ขั้น 1':(!creating&&previewJob===player.job?'ขั้น 2 · อาชีพปัจจุบัน':'ตัวอย่างขั้น 2');$('previewJob').textContent=JOBS[previewJob].name;renderRatings(previewJob);drawCharacterPreview();document.querySelectorAll('[data-branch]').forEach(b=>{const selected=b.dataset.branch===previewJob;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))});const lv=creating?1:player.level,token=creating?0:player.promotionTokens,advanced=!creating&&player.job!=='swordsman';$('levelRequirement').textContent=(lv>=30?'✓ ':'○ ')+'เลเวล '+lv+' / '+ADVANCEMENT_LEVEL;$('levelRequirement').className=lv>=30?'met':'';$('itemRequirement').textContent=advanced?'✓ เปลี่ยนอาชีพขั้น 2 แล้ว':(token?'✓ ':'○ ')+'ตรานักรบ '+token+' / 1 ชิ้น';$('itemRequirement').className=token||advanced?'met':'';$('promoteBtn').disabled=creating||!canPromote()||previewJob==='swordsman';$('promoteBtn').textContent=advanced?'เปลี่ยนเป็น'+JOBS[player.job].name+'แล้ว':previewJob==='swordsman'?'เลือกสายอาชีพขั้น 2':'เปลี่ยนเป็น'+JOBS[previewJob].name;$('creatorSummary').textContent=creating?'สร้างเป็นนักดาบขั้น 1 · เลือกสายขั้น 2 ภายหลัง':advanced?'อาชีพปัจจุบัน: '+JOBS[player.job].name+' · ขั้น 3–5 ยังไม่เปิด':canPromote()?'พร้อมเปลี่ยนอาชีพ · ใช้ตรานักรบ 1 ชิ้น':'ต้องมีเลเวล 30 และตรานักรบก่อนเปลี่ยนอาชีพ';$('careerTrialBtn').hidden=creating||advanced||token>0;$('careerTrialBtn').disabled=!canEnterTrial();$('careerTrialBtn').textContent=lv>=30?'เข้าด่านบอส · บททดสอบนักรบ':'ด่านบอสปลดล็อกที่ Lv.30'}
function buildBranches(){$('branches').replaceChildren();for(const branch of BRANCHES){const b=document.createElement('button');b.className='branch';b.type='button';b.dataset.branch=branch.id;b.setAttribute('aria-pressed','false');b.innerHTML='<span class="branch-icon" aria-hidden="true">'+branch.icon+'</span><span><strong>'+JOBS[branch.id].name+'</strong><small>'+branch.summary+'</small></span><span class="branch-tag">'+branch.tag+'</span>';b.onclick=()=>{previewJob=branch.id;updateCareerPreview()};$('branches').append(b)}}
function showCreator(mode){creatorMode=mode;const creating=mode==='create';document.querySelector('.advancement-requirements').hidden=creating;previewJob=creating?'swordsman':player.job;$('creatorTitle').textContent=creating?'สร้างตัวละคร':'เส้นทางอาชีพ';$('creatorEyebrow').textContent=creating?'SAVE '+String(pendingSlot+1).padStart(2,'0')+' / A NEW BEGINNING':'WARRIOR / CLASS ADVANCEMENT';$('creatorBack').textContent=creating?'← กลับเลือกเซฟ':'← กลับหมู่บ้าน';$('characterName').value=creating?'Fern':player.name;$('characterName').readOnly=!creating;$('characterName').setCustomValidity('');$('creatorError').textContent='';$('createCharacterBtn').hidden=!creating;$('promoteBtn').hidden=creating;$('branchHint').textContent='กดดูตัวละครและแนวทางของแต่ละสาย · ขั้น 3–5 จะเปิดภายหลัง';buildBranches();switchScreen('creator');updateCareerPreview()}
function openCreator(index){if(!Number.isInteger(index)||index<0||index>=3||slots[index])return;activeSlot=-1;pendingSlot=index;showCreator('create')}
function openCareer(){if(activeSlot<0||player.map!=='town')return;if(player.job==='swordsman'&&player.level>=30){showAdvancementQuest();return}save();pendingSlot=-1;showCreator('career')}
function leaveCreator(){if(creatorMode==='create'){pendingSlot=-1;switchScreen('saves')}else{switchScreen('play');updateUI()}}
function createCharacter(event){event.preventDefault();if(screen!=='creator'||creatorMode!=='create'||pendingSlot<0||slots[pendingSlot])return;const name=$('characterName').value.trim().normalize('NFC');if(!name||name.length>24){$('characterName').setCustomValidity('กรุณาตั้งชื่อ 1–24 ตัวอักษร');$('characterName').reportValidity();return}const index=pendingSlot;slots[index]={character:{...fresh(),name},savedAt:new Date().toISOString()};pendingSlot=-1;persist();loadSlot(index)}
function promoteCharacter(job){if(!canPromote()||!BRANCHES.some(b=>b.id===job))return false;player.job=job;player.promotionTokens--;player.questState='completed';player.secondSkills=validateSecondSkills(undefined,job);player.secondSP+=10+3*Math.max(0,Math.min(60,player.level)-30);save();previewJob=job;updateCareerPreview();toast('เปลี่ยนอาชีพเป็น'+JOBS[job].name+'แล้ว');return true}
function requestPromotion(){const job=previewJob;if(!canPromote()||job==='swordsman')return;modal('เปลี่ยนเป็น'+JOBS[job].name+'?','ใช้ตรานักรบ 1 ชิ้นเพื่อเปลี่ยนเป็นอาชีพขั้น 2 สายนี้ เมื่อยืนยันแล้วจะเปลี่ยนไปสายอื่นไม่ได้',[['กลับไปเลือก',closeModal],['ยืนยันเปลี่ยนอาชีพ',()=>{closeModal();promoteCharacter(job)},true]])}
function renderTrialEntry(){$('trialEntry').replaceChildren();const box=document.createElement('div');box.className='trial-entry';const text=document.createElement('div');const title=document.createElement('strong');title.textContent='ด่านบอส · บททดสอบนักรบ';const description=document.createElement('p');description.textContent=player.job!=='swordsman'?'เปลี่ยนอาชีพขั้น 2 แล้ว':player.promotionTokens?'มีตรานักรบแล้ว · พร้อมเลือกอาชีพขั้น 2':'Lv.30 · โค่นราชาสไลม์ รับตรานักรบเพื่อเปลี่ยนอาชีพ';text.append(title,description);const b=document.createElement('button');b.id='trialStartBtn';b.disabled=player.promotionTokens?false:!canEnterTrial();b.textContent=player.promotionTokens?'เลือกอาชีพขั้น 2':canEnterTrial()?'เข้าท้าทาย':'ล็อก';b.onclick=()=>player.promotionTokens?openCareer():beginStage(4);box.append(text,b);$('trialEntry').append(box)}
function renderStages(){renderStoryStages();renderTrialEntry();selectStageCategory(stageCategory)}
$('creatorBack').onclick=leaveCreator;$('characterForm').onsubmit=createCharacter;$('characterName').oninput=()=>{$('characterName').setCustomValidity('');drawCharacterPreview()};$('warriorChoice').onclick=()=>{previewJob='swordsman';updateCareerPreview()};$('promoteBtn').onclick=requestPromotion;$('careerBtn').onclick=openCareer;$('careerTrialBtn').onclick=()=>beginStage(4);

